const express = require('express');
const Y = require('yjs');
const db = require('../db');

const app = express();
app.use(express.raw({ type: 'application/octet-stream', limit: '10mb' }));

app.post('/api/documents/:docId/crdt-updates', async (req, res) => {
  const { docId } = req.params;
  const updateBlob = req.body;

  if (!updateBlob || !Buffer.isBuffer(updateBlob)) {
    return res.status(400).json({ error: 'Binary update blob required' });
  }

  // Verify write permission on target document
  const permission = await db('document_collaborators')
    .where({ document_id: docId, user_id: req.user.id })
    .andWhere('role', 'in', ['editor', 'owner'])
    .first();

  if (!permission) {
    return res.status(403).json({ error: 'Forbidden: Insufficient permissions to submit updates' });
  }

  await db('crdt_updates').insert({
    document_id: docId,
    update_data: updateBlob,
    user_id: req.user.id,
    applied_at: new Date()
  });

  return res.json({ status: 'update_applied', documentId: docId });
});

module.exports = app;
